import csv
import sys


def report_orders(stream):
    rows = csv.DictReader(stream)
    included = (row for row in rows if row["refunded"] != "yes")
    amounts = [float(row["amount"]) for row in included]
    return {"count": len(amounts), "total": sum(amounts)}


def main():
    if len(sys.argv) != 2:
        raise SystemExit("usage: python3 orders_corrected.py ORDERS.csv")
    with open(sys.argv[1], newline="", encoding="utf-8") as stream:
        report = report_orders(stream)
    print(f"count={report['count']}")
    print(f"total={report['total']:.2f}")


if __name__ == "__main__":
    main()

import json
import sys
from collections import defaultdict, deque


STEP_FIELDS = {
    "id",
    "name",
    "owner",
    "dependsOn",
    "files",
    "verification",
    "recovery",
    "criteria",
}

JSON_LIKE_NON_EXECUTABLES = {
    "[]",
    "{}",
    "null",
    "true",
    "false",
}


def nonempty_string(value):
    return isinstance(value, str) and bool(value.strip())


def string_list(value):
    return isinstance(value, list) and all(
        nonempty_string(item) for item in value
    )


def verification_error(value):
    if not nonempty_string(value):
        return "verification must be a nonempty structured string"

    parts = value.split("|")
    kind = parts[0]
    fields = {}

    for part in parts[1:]:
        if "=" not in part:
            return "verification fields must use key=value"
        key, field_value = part.split("=", 1)
        if not nonempty_string(key) or not nonempty_string(field_value):
            return "verification fields must be unique and nonempty"
        if key in fields:
            return "verification fields must be unique and nonempty"
        fields[key] = field_value

    if kind == "command":
        if set(fields) != {"argv", "expect"}:
            return "command verification requires exactly argv and expect"

        argv = fields["argv"].split(",")
        if not argv or not all(nonempty_string(token) for token in argv):
            return "command verification requires nonempty comma-separated argv tokens"

        executable = argv[0].strip()
        if (
            executable.lower() in JSON_LIKE_NON_EXECUTABLES
            or executable.startswith("[")
            or executable.startswith("{")
        ):
            return "command argv must start with a concrete executable token"

        if fields["expect"] != "exit:0":
            return "command verification requires expect=exit:0"
        return None

    if kind == "review":
        if set(fields) != {"targets", "check", "evidence"}:
            return "review verification requires exactly targets, check, and evidence"
        if not all(nonempty_string(fields[name]) for name in fields):
            return "review verification fields must be nonempty"
        return None

    return "verification kind must be command or review"


def display_keys(keys):
    return ",".join(sorted((str(key) for key in keys)))


def check_plan(plan):
    errors = []

    if not isinstance(plan, dict):
        return ["plan root must be an object"]

    acceptance = plan.get("acceptanceCriteria")
    criteria = set()
    if not isinstance(acceptance, dict) or not acceptance:
        errors.append("acceptanceCriteria must be a nonempty object")
    else:
        for criterion, description in acceptance.items():
            if not nonempty_string(criterion) or not nonempty_string(description):
                errors.append(
                    "acceptanceCriteria entries require nonempty string IDs and descriptions"
                )
            else:
                criteria.add(criterion)

    steps = plan.get("steps")
    if not isinstance(steps, list) or not steps:
        errors.append("steps must be a nonempty array")
        return errors

    ids = []
    seen = set()
    object_steps = []

    for index, step in enumerate(steps):
        if not isinstance(step, dict):
            errors.append(f"step at index {index} must be an object")
            continue

        object_steps.append((index, step))
        step_keys = set(step.keys())
        missing = STEP_FIELDS - step_keys
        extra = step_keys - STEP_FIELDS
        if missing:
            errors.append(
                f"missing step fields at index {index}: {display_keys(missing)}"
            )
        if extra:
            errors.append(
                f"unknown step fields at index {index}: {display_keys(extra)}"
            )

        step_id = step.get("id")
        valid_id = nonempty_string(step_id)
        label = step_id if valid_id else f"index {index}"

        if not valid_id:
            errors.append(f"missing step ID at index {index}")
        else:
            ids.append(step_id)
            if step_id in seen:
                errors.append(f"duplicate step ID: {step_id}")
            else:
                seen.add(step_id)

        if not nonempty_string(step.get("name")):
            errors.append(f"missing name: {label}")
        if not nonempty_string(step.get("owner")):
            errors.append(f"missing owner: {label}")
        if not string_list(step.get("dependsOn")):
            errors.append(
                f"dependsOn must be an array of nonempty strings: {label}"
            )
        if not string_list(step.get("files")):
            errors.append(f"files must be an array of nonempty strings: {label}")
        if not string_list(step.get("criteria")):
            errors.append(
                f"criteria must be an array of nonempty strings: {label}"
            )
        if not nonempty_string(step.get("recovery")):
            errors.append(f"missing recovery: {label}")

        detail = verification_error(step.get("verification"))
        if detail:
            errors.append(f"non-concrete verification: {label}: {detail}")

    dependencies = {}
    children = defaultdict(list)
    mapped = set()

    for index, step in object_steps:
        step_id = step.get("id")
        if not nonempty_string(step_id) or step_id not in seen:
            continue

        raw_dependencies = step.get("dependsOn")
        dependencies[step_id] = []
        if string_list(raw_dependencies):
            dependencies[step_id] = list(raw_dependencies)
            for dependency in raw_dependencies:
                if dependency not in seen:
                    errors.append(f"unknown dependency: {step_id} -> {dependency}")
                else:
                    children[dependency].append(step_id)

        raw_mappings = step.get("criteria")
        if string_list(raw_mappings):
            for criterion in raw_mappings:
                if criterion not in criteria:
                    errors.append(
                        f"unknown criterion mapping: {step_id} -> {criterion}"
                    )
                else:
                    mapped.add(criterion)

    for criterion in sorted(criteria - mapped):
        errors.append(f"unmapped acceptance criterion: {criterion}")

    state = {step_id: 0 for step_id in ids}
    cycle_reports = set()

    def visit(step_id):
        if state[step_id] == 1:
            if step_id not in cycle_reports:
                errors.append(f"dependency cycle includes: {step_id}")
                cycle_reports.add(step_id)
            return
        if state[step_id] == 2:
            return

        state[step_id] = 1
        for dependency in dependencies.get(step_id, []):
            if dependency in state:
                visit(dependency)
        state[step_id] = 2

    for step_id in ids:
        if state[step_id] == 0:
            visit(step_id)

    def reaches(start, target):
        queue = deque([start])
        visited = set()
        while queue:
            current = queue.popleft()
            if current == target:
                return True
            if current in visited:
                continue
            visited.add(current)
            queue.extend(children[current])
        return False

    claims = defaultdict(list)
    for index, step in object_steps:
        step_id = step.get("id")
        if not nonempty_string(step_id) or step_id not in seen:
            continue

        raw_files = step.get("files")
        if not string_list(raw_files):
            continue
        for filename in raw_files:
            claims[filename].append(step_id)

    for filename in sorted(claims):
        claimants = claims[filename]
        for index, first in enumerate(claimants):
            for second in claimants[index + 1:]:
                if (
                    first != second
                    and not reaches(first, second)
                    and not reaches(second, first)
                ):
                    errors.append(
                        f"unordered file ownership conflict: {filename}: "
                        f"{first}, {second}"
                    )

    return errors


def main():
    if len(sys.argv) != 2:
        print("REJECTED")
        print("- usage: python3 plan_checker.py PLAN.json")
        raise SystemExit(1)

    try:
        with open(sys.argv[1], encoding="utf-8") as stream:
            plan = json.load(stream)
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        print("REJECTED")
        print(f"- invalid JSON input: {error.__class__.__name__}")
        raise SystemExit(1)

    errors = check_plan(plan)
    if errors:
        print("REJECTED")
        for error in errors:
            print(f"- {error}")
        raise SystemExit(1)

    print(
        "ACCEPTED: structural checks passed; "
        "behavioral correctness still requires tests"
    )


if __name__ == "__main__":
    main()
